81	            (Include(lhs), Include(rhs)) => Include(lhs | rhs),
82	            (Include(lhs), Exclude(rhs)) => Exclude(rhs - lhs),
83	            (Exclude(lhs), Include(rhs)) => Exclude(lhs - rhs),
