use base64::{prelude::BASE64_STANDARD, DecodeError, Engine};
use thiserror::Error;

pub const DEFAULT_BLOCK_SIZE: u32 = 128;

/// A single scored document returned by a sparse similarity query.
///
/// Ordering is intentionally *reversed* by score (and then by offset) so
/// that a [`std::collections::BinaryHeap<Score>`] behaves as a min-heap on
/// `score`: the heap root is the lowest-scoring candidate, which is the one
/// evicted when a better candidate arrives. `into_sorted_vec()` on such a
/// heap therefore yields results in descending score order.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Score {
    pub score: f32,
    pub offset: u32,
}

impl Eq for Score {}

impl Ord for Score {
    fn cmp(&self, other: &Self) -> Ordering {
        self.score
            .total_cmp(&other.score)
            .then(self.offset.cmp(&other.offset))
            .reverse()
    }
}

impl PartialOrd for Score {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
